using System.Globalization;using System.Text.Json;using WAID.Application.Abstractions;using WAID.Application.Services;using WAID.Domain.Diagnostics;using WAID.Domain.Repairs;using WAID.Health;using WAID.Infrastructure.Diagnostics;
namespace WAID.Infrastructure.Persistence;
public sealed class SqliteReliabilityTimelineSource(WaidDatabase database):IReliabilityTimelineSource
{
 private static readonly JsonSerializerOptions Json=new(JsonSerializerDefaults.Web);
 public async Task<IReadOnlyList<NormalizedTimelineRecord>>ReadAsync(DateTimeOffset? fromUtc,DateTimeOffset? toUtc,int maximumRecords,CancellationToken token){if(maximumRecords is<1 or>100_000)throw new ArgumentOutOfRangeException(nameof(maximumRecords));var items=new List<NormalizedTimelineRecord>();await Findings(items,maximumRecords,token);await Repairs(items,maximumRecords,token);await Drivers(items,maximumRecords,token);await Updates(items,maximumRecords,token);await Health(items,maximumRecords,token);await Alerts(items,maximumRecords,token);await Retention(items,token);return items.Where(x=>(fromUtc is null||x.OccurredAtUtc>=fromUtc)&&(toUtc is null||x.OccurredAtUtc<=toUtc)).OrderByDescending(x=>x.OccurredAtUtc).Take(maximumRecords).ToArray();}
 private async Task Findings(List<NormalizedTimelineRecord>items,int max,CancellationToken t){await using var c=database.OpenConnection();await using var q=c.CreateCommand();q.CommandText="SELECT f.id,f.scanner_id,f.code,f.title,f.description,f.severity,f.evidence_json,s.completed_utc FROM findings f JOIN scan_sessions s ON s.id=f.session_id ORDER BY s.completed_utc DESC LIMIT $max";q.Parameters.AddWithValue("$max",max);await using var r=await q.ExecuteReaderAsync(t);while(await r.ReadAsync(t)){var scanner=r.GetString(1);var code=r.GetString(2);var kind=code.Contains("CRASH",StringComparison.OrdinalIgnoreCase)||code.Contains("BSOD",StringComparison.OrdinalIgnoreCase)?ReliabilityEventKind.Crash:scanner.Contains("reliability",StringComparison.OrdinalIgnoreCase)?ReliabilityEventKind.ReliabilityEvent:code.Contains("UPDATE",StringComparison.OrdinalIgnoreCase)?ReliabilityEventKind.Update:scanner.Contains("driver",StringComparison.OrdinalIgnoreCase)?ReliabilityEventKind.DriverChange:ReliabilityEventKind.Alert;items.Add(new(kind,Parse(r.GetString(7)),Safe(r.GetString(3)),Safe(r.GetString(4)),Map((DiagnosticSeverity)r.GetInt32(5)),code,new("finding",r.GetString(0),$"scanner:{scanner}"),SafeEvidence(r.GetString(6))));}}
 private async Task Repairs(List<NormalizedTimelineRecord>items,int max,CancellationToken t){await using var c=database.OpenConnection();await using var q=c.CreateCommand();q.CommandText="SELECT transaction_id,repair_id,status,created_utc,summary FROM repair_history ORDER BY created_utc DESC LIMIT $max";q.Parameters.AddWithValue("$max",max);await using var r=await q.ExecuteReaderAsync(t);while(await r.ReadAsync(t)){var status=(RepairTransactionStatus)r.GetInt32(2);items.Add(new(ReliabilityEventKind.Repair,Parse(r.GetString(3)),r.GetString(1),r.IsDBNull(4)?status.ToString():Safe(r.GetString(4)),status==RepairTransactionStatus.Failed?ReliabilitySeverity.Warning:ReliabilitySeverity.Information,r.GetString(1),new("repair",r.GetString(0),$"repair:{r.GetString(1)}"),new Dictionary<string,string>{{"status",status.ToString()}}));}}
 private async Task Drivers(List<NormalizedTimelineRecord>items,int max,CancellationToken t){await using var c=database.OpenConnection();await using var q=c.CreateCommand();q.CommandText="SELECT id,report_json FROM driver_analysis_runs ORDER BY generated_utc DESC LIMIT $max";q.Parameters.AddWithValue("$max",max);await using var r=await q.ExecuteReaderAsync(t);while(await r.ReadAsync(t)){var report=JsonSerializer.Deserialize<DriverHealthReport>(r.GetString(1),Json);if(report is null)continue;foreach(var x in report.Changes)items.Add(new(ReliabilityEventKind.DriverChange,x.DetectedAtUtc,$"Driver {Safe(x.ChangeType)}",Safe(x.DeviceName),ReliabilitySeverity.Advisory,x.DeviceKey,new("driver-analysis",r.GetString(0),$"driver:{x.DeviceKey}"),new Dictionary<string,string>{{"changeType",Safe(x.ChangeType)}}));}}
 private async Task Updates(List<NormalizedTimelineRecord>items,int max,CancellationToken t){await using var c=database.OpenConnection();await using var q=c.CreateCommand();q.CommandText="SELECT id,report_json FROM windows_update_analysis_runs ORDER BY generated_utc DESC LIMIT $max";q.Parameters.AddWithValue("$max",max);await using var r=await q.ExecuteReaderAsync(t);while(await r.ReadAsync(t)){var report=JsonSerializer.Deserialize<WindowsUpdateHealthReport>(r.GetString(1),Json);if(report is null)continue;foreach(var x in report.Attempts)items.Add(new(ReliabilityEventKind.Update,x.OccurredAtUtc,Safe(x.Title),x.State==UpdateAttemptState.Failed?$"Update failed with {Safe(x.ErrorCode)}":x.State.ToString(),x.State==UpdateAttemptState.Failed?ReliabilitySeverity.Warning:ReliabilitySeverity.Information,x.KnowledgeBaseId??x.Title,new("windows-update-analysis",r.GetString(0),Safe(x.SourceReference)),new Dictionary<string,string>{{"state",x.State.ToString()},{"errorCode",Safe(x.ErrorCode)}}));}}
 private async Task Health(List<NormalizedTimelineRecord>items,int max,CancellationToken t){var snapshots=new List<HealthSnapshot>();await using var c=database.OpenConnection();await using var q=c.CreateCommand();q.CommandText="SELECT id,snapshot_json FROM health_snapshots ORDER BY captured_utc ASC LIMIT $max";q.Parameters.AddWithValue("$max",max);await using var r=await q.ExecuteReaderAsync(t);while(await r.ReadAsync(t)){var x=JsonSerializer.Deserialize<HealthSnapshot>(r.GetString(1),Json);if(x is not null)snapshots.Add(x);}for(var i=1;i<snapshots.Count;i++){var delta=snapshots[i].Health.Overall-snapshots[i-1].Health.Overall;if(Math.Abs(delta)<10)continue;items.Add(new(ReliabilityEventKind.HealthShift,snapshots[i].CapturedAtUtc,delta<0?"Health score declined":"Health score improved",$"Overall health changed by {delta:+0;-0} points.",delta<0?ReliabilitySeverity.Warning:ReliabilitySeverity.Information,"overall-health",new("health-snapshot",snapshots[i].Id.ToString(),$"health:{snapshots[i].Id}"),new Dictionary<string,string>{{"change",delta.ToString(CultureInfo.InvariantCulture)},{"score",snapshots[i].Health.Overall.ToString(CultureInfo.InvariantCulture)}}));}}
 private async Task Alerts(List<NormalizedTimelineRecord>items,int max,CancellationToken t){await using var c=database.OpenConnection();await using var q=c.CreateCommand();q.CommandText="SELECT id,sample_json FROM monitoring_samples WHERE json_extract(sample_json,'$.severity') IN (2,3) ORDER BY captured_utc DESC LIMIT $max";q.Parameters.AddWithValue("$max",max);await using var r=await q.ExecuteReaderAsync(t);while(await r.ReadAsync(t)){var x=JsonSerializer.Deserialize<LiveSignalSample>(r.GetString(1),Json);if(x is null)continue;items.Add(new(ReliabilityEventKind.Alert,x.CapturedAtUtc,$"{Safe(x.SignalId)} monitoring alert",$"{x.Value?.ToString(CultureInfo.InvariantCulture)??"Unavailable"} {Safe(x.Unit)}",x.Severity==LiveSignalSeverity.Critical?ReliabilitySeverity.Critical:ReliabilitySeverity.Warning,x.SignalId,new("monitoring-sample",r.GetString(0),$"monitor:{x.SignalId}"),new Dictionary<string,string>{{"severity",x.Severity.ToString()},{"source",Safe(x.Source)}}));}}
 private async Task Retention(List<NormalizedTimelineRecord>items,CancellationToken t){await using var c=database.OpenConnection();await using var q=c.CreateCommand();q.CommandText="SELECT state_json FROM monitoring_retention WHERE id=1";var json=await q.ExecuteScalarAsync(t)as string;if(json is null)return;var x=JsonSerializer.Deserialize<MonitoringRetentionState>(json,Json);if(x is null||x.DeletedSamples<=0)return;items.Add(new(ReliabilityEventKind.RetentionGap,x.RetainAfterUtc,"Earlier monitoring history was retained out",$"{x.DeletedSamples} bounded monitoring records were removed by retention.",ReliabilitySeverity.Unavailable,"retention",new("monitoring-retention","1","retention:monitoring"),new Dictionary<string,string>{{"deletedSamples",x.DeletedSamples.ToString(CultureInfo.InvariantCulture)}}));}
 private static DateTimeOffset Parse(string value)=>DateTimeOffset.Parse(value,CultureInfo.InvariantCulture).ToUniversalTime();private static ReliabilitySeverity Map(DiagnosticSeverity s)=>s switch{DiagnosticSeverity.Critical=>ReliabilitySeverity.Critical,DiagnosticSeverity.Warning=>ReliabilitySeverity.Warning,DiagnosticSeverity.Information=>ReliabilitySeverity.Information,_=>ReliabilitySeverity.Advisory};private static string Safe(string value)=>ReportRedactor.RedactText(value);private static IReadOnlyDictionary<string,string>SafeEvidence(string json){try{var values=JsonSerializer.Deserialize<Dictionary<string,string>>(json)??[];return values.Where(x=>x.Key is"eventId"or"provider"or"errorCode"or"state"or"resultCode").ToDictionary(x=>x.Key,x=>Safe(x.Value));}catch(JsonException){return new Dictionary<string,string>();}}
}
